"use strict";
// Compiled natively. The island module's members bound by a `var` pattern
// and the whole module by a `let`; a member passed on as an argument.
var { find, Jar } = require("pantry");
let pantry = require("pantry");

var salt = find("salt").grams;

exports.total = function total(name) {
  return salt + find(name).grams + pantry.find(name).grams;
};
exports.labelVia = function labelVia(pick) {
  return pick(find);
};
exports.jarOf = function jarOf(label, count) {
  return new Jar(label, count).describe();
};
